-- Authorized local rollback fixtures; no users, providers or production writes.
begin;
set local lock_timeout='5s';set local statement_timeout='90s';
truncate public.project_campaign_placement_revisions,public.project_campaign_placement_commands,public.project_campaign_placements;
select set_config('request.jwt.claim.sub','99999999-9999-4999-8999-999999999902',true);
-- Known clone-only legacy activity default; exact restoration checked by the harness.
alter table public.activity_events alter column organization_id set default '99999999-9999-4999-8999-999999999901'::uuid;
insert into public.tasks(id,organization_id,project_id,user_id,created_by,title,department_id,due_date,status)
values('99999999-9999-4999-8999-999999997241','99999999-9999-4999-8999-999999999901','99999999-9999-4999-8999-999999999974','99999999-9999-4999-8999-999999999902','99999999-9999-4999-8999-999999999902','Synthetic existing Project Task reference','marketing','2026-10-10','backlog');
create function pg_temp.check_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end $$;
create function pg_temp.expect_error(query text,code text,label text) returns void language plpgsql as $$begin begin execute query;exception when others then if sqlstate=code then raise notice 'PASS %',label;return;end if;raise exception 'FAIL % expected % got %: %',label,code,sqlstate,sqlerrm;end;raise exception 'FAIL % did not reject',label;end $$;
do $$declare org uuid:='99999999-9999-4999-8999-999999999901';project uuid:='99999999-9999-4999-8999-999999999974';campaign uuid:='99999999-9999-4999-8999-999999997172';request uuid:='99999999-9999-4999-8999-999999997250';asset uuid;variant uuid;account uuid;registration jsonb;registered jsonb;input jsonb;review jsonb;saved jsonb;paid jsonb;next_input jsonb;task_count bigint;work_count bigint;source_count bigint;
begin
 select id into asset from public.project_campaign_assets where organization_id=org and project_id=project and source_kind='artifact_version' and source_version_id='99999999-9999-4999-8999-999999997111';
 if asset is null then raise exception 'Verified local AD2 shared-source fixture absent';end if;
 registration:=jsonb_build_object('command_kind','register_variant','campaign_id',campaign,'plan_version_id','99999999-9999-4999-8999-999999997173','marketing_service_id','99999999-9999-4999-8999-999999997171','source_kind','artifact_version','source_version_id','99999999-9999-4999-8999-999999997180','asset_id',asset,'label','Synthetic placement organic variant');
 registered:=public.preview_project_campaign_asset(org,project,registration);registered:=public.confirm_project_campaign_asset(org,project,registration,registered->>'review_sha256','99999999-9999-4999-8999-999999997242');variant:=(registered->>'variant_id')::uuid;
 select id into account from public.project_reporting_bindings where organization_id=org and project_id=project and connection_id='99999999-9999-4999-8999-999999997230';
 input:=jsonb_build_object('asset_id',asset,'variant_id',variant,'campaign_plan_version_id','99999999-9999-4999-8999-999999997173','marketing_service_id','99999999-9999-4999-8999-999999997171','channel','Facebook','account_binding_id',account,'mode','organic','scheduled_at','2026-10-10T09:00:00.000Z','time_zone','Asia/Karachi','cta',jsonb_build_object('label','Read the article','url','https://example.invalid/article?utm_campaign=launch'),'external_id',null,'recorded_url',null,'publication_state','planned','contribution',jsonb_build_object('kind','project_task','id','99999999-9999-4999-8999-999999997241'));
 select count(*) into task_count from public.tasks;select count(*) into work_count from public.work_items;select count(*) into source_count from public.artifact_versions;
 review:=public.preview_project_campaign_placement(org,project,campaign,null,0,input);
 perform pg_temp.check_true((select count(*) from public.project_campaign_placements)=0 and (select count(*) from public.project_campaign_placement_commands)=0,'Exact placement review makes zero writes');
 perform pg_temp.check_true(review#>>'{reference,source,version_id}'='99999999-9999-4999-8999-999999997111' and review#>>'{reference,variant,version_id}'='99999999-9999-4999-8999-999999997180','Placement retains one original exact source and distinct reviewed variant');
 perform pg_temp.check_true(review#>>'{reference,contribution,kind}'='project_task' and review#>>'{reference,contribution,due_date}'='2026-10-10' and review#>>'{reference,external_write_authorized}'='false','Existing task deadline/identity derived without reassignment/provider authority');
 saved:=public.confirm_project_campaign_placement(org,project,campaign,null,0,input,review->>'review_sha256',request);
 perform pg_temp.check_true(saved->>'revision_number'='1' and saved->>'asset_id'=asset::text and saved->>'external_write_authorized'='false' and saved->>'internal_ready'='false','One internal organic placement records exact reviewed identity');
 perform pg_temp.check_true((select count(*) from public.tasks)=task_count and (select count(*) from public.work_items)=work_count and (select count(*) from public.artifact_versions)=source_count,'Placement creates no Tasks, Work Items or canonical source versions');
 perform pg_temp.check_true(public.confirm_project_campaign_placement(org,project,campaign,null,0,input,review->>'review_sha256',request)->>'replayed'='true' and (select count(*) from public.project_campaign_placement_commands)=1,'Original UUID replays exactly one placement revision');
 perform pg_temp.expect_error(format('select public.confirm_project_campaign_placement(%L,%L,%L,null,0,%L::jsonb,%L,%L)',org,project,campaign,input||'{"mode":"paid"}',review->>'review_sha256',request),'23505','Changed organic/paid payload under same UUID rejected');
 perform pg_temp.check_true(public.get_project_campaign_placement_operation(org,project,request)#>>'{result,placement_id}'=saved->>'placement_id' and public.get_project_campaign_placement_operation(org,project,'99999999-9999-4999-8999-999999997259') is null,'Original placement recovery uses exact UUID without latest fallback');
 paid:=input||jsonb_build_object('mode','paid','channel','Advertising','variant_id',null,'account_binding_id',null,'contribution',jsonb_build_object('kind','engagement_work_item','id','99999999-9999-4999-8999-999999997160'));
 review:=public.preview_project_campaign_placement(org,project,campaign,null,0,paid);
 perform pg_temp.check_true(review#>>'{reference,blocking_reasons,0}'='account_binding_missing' and review#>>'{reference,contribution,kind}'='engagement_work_item','Missing account stays explicit; existing Work Item remains a separate canonical category');
 registered:=public.confirm_project_campaign_placement(org,project,campaign,null,0,paid,review->>'review_sha256','99999999-9999-4999-8999-999999997251');
 perform pg_temp.check_true(registered->>'asset_id'=saved->>'asset_id' and registered->>'placement_id'<>saved->>'placement_id' and (select count(*) from public.work_items)=work_count,'Organic/paid placements retain one canonical source and never clone work');
 next_input:=input||jsonb_build_object('external_id','manual-post-123','recorded_url','https://example.invalid/post/123?utm_source=launch','publication_state','recorded_published');
 review:=public.preview_project_campaign_placement(org,project,campaign,(saved->>'placement_id')::uuid,1,next_input);
 perform public.confirm_project_campaign_placement(org,project,campaign,(saved->>'placement_id')::uuid,1,next_input,review->>'review_sha256','99999999-9999-4999-8999-999999997252');
 perform pg_temp.check_true((select data->>'external_id' from public.project_campaign_placement_revisions where placement_id=(saved->>'placement_id')::uuid and revision_number=2)='manual-post-123' and (select count(*) from public.project_campaign_placements)=2,'Manually recorded publication appends immutable evidence without external action');
 perform pg_temp.expect_error(format('select public.preview_project_campaign_placement(%L,%L,%L,%L,1,%L::jsonb)',org,project,campaign,saved->>'placement_id',input),'40001','Stale competing placement revision rejected');
 review:=public.preview_project_campaign_placement(org,project,campaign,(saved->>'placement_id')::uuid,2,next_input);
 update public.tasks set due_date='2026-10-11' where id='99999999-9999-4999-8999-999999997241';
 perform pg_temp.expect_error(format('select public.confirm_project_campaign_placement(%L,%L,%L,%L,2,%L::jsonb,%L,%L)',org,project,campaign,saved->>'placement_id',next_input,review->>'review_sha256','99999999-9999-4999-8999-999999997253'),'40001','Canonical task revision/deadline change invalidates exact review');
 update public.engagement_services set status='on_hold' where id='99999999-9999-4999-8999-999999997171';
 perform pg_temp.expect_error(format('select public.preview_project_campaign_placement(%L,%L,%L,%L,2,%L::jsonb)',org,project,campaign,saved->>'placement_id',next_input),'42501','Unavailable Marketing service blocks new placement edits');
 next_input:=next_input||'{"publication_state":"paused"}';review:=public.preview_project_campaign_placement(org,project,campaign,(saved->>'placement_id')::uuid,2,next_input);
 perform pg_temp.check_true(review#>>'{reference,planning_state_only}'='true','Stopping an existing plan remains available after source/service withdrawal');
 perform public.confirm_project_campaign_placement(org,project,campaign,(saved->>'placement_id')::uuid,2,next_input,review->>'review_sha256','99999999-9999-4999-8999-999999997254');
 perform pg_temp.expect_error(format('select public.preview_project_campaign_placement(%L,%L,%L,%L,3,%L::jsonb)',org,project,campaign,saved->>'placement_id',next_input||'{"cta":{"label":"Changed unapproved message","url":null}}'),'22023','Pause/cancel cannot smuggle other data edits after withdrawal');
 next_input:=next_input||'{"publication_state":"cancelled"}';review:=public.preview_project_campaign_placement(org,project,campaign,(saved->>'placement_id')::uuid,3,next_input);
 perform pg_temp.check_true(public.confirm_project_campaign_placement(org,project,campaign,(saved->>'placement_id')::uuid,3,next_input,review->>'review_sha256','99999999-9999-4999-8999-999999997255')->>'revision_number'='4','Cancellation appends exact original source history after withdrawal');
 update public.engagement_services set status='active' where id='99999999-9999-4999-8999-999999997171';
 perform pg_temp.expect_error(format('select public.preview_project_campaign_placement(%L,%L,%L,null,0,%L::jsonb)',org,project,campaign,input||'{"publish":true}'),'22023','Unscoped publishing field rejected');
 perform pg_temp.expect_error(format('select public.preview_project_campaign_placement(%L,%L,%L,null,0,%L::jsonb)',org,project,campaign,input||'{"budget":1000}'),'22023','Unscoped spend field rejected');
 perform pg_temp.expect_error(format('select public.preview_project_campaign_placement(%L,%L,%L,null,0,%L::jsonb)',org,project,campaign,input||'{"assignee_id":"99999999-9999-4999-8999-999999999902"}'),'22023','Placement cannot add a parallel assignment authority');
 perform pg_temp.expect_error(format('select public.preview_project_campaign_placement(%L,%L,%L,null,0,%L::jsonb)',org,project,campaign,input||'{"scheduled_at":"2026-02-30T09:00:00Z"}'),'22023','Invalid calendar date rejected natively');
 perform pg_temp.expect_error(format('select public.preview_project_campaign_placement(%L,%L,%L,null,0,%L::jsonb)',org,project,campaign,input||'{"time_zone":"invented/zone"}'),'22023','Unknown timezone cannot use implicit local time');
 perform pg_temp.expect_error(format('select public.preview_project_campaign_placement(%L,%L,%L,null,0,%L::jsonb)',org,project,campaign,input||'{"scheduled_at":"2026-10-10T09:00:00"}'),'22023','Ambiguous local-time schedule rejected');
 perform pg_temp.expect_error(format('select public.preview_project_campaign_placement(%L,%L,%L,null,0,%L::jsonb)',org,project,campaign,input||'{"recorded_url":"https://user:secret@example.invalid/post"}'),'22023','Recorded publication URL cannot carry credentials');
 perform pg_temp.expect_error(format('select public.preview_project_campaign_placement(%L,%L,%L,null,0,%L::jsonb)',org,project,campaign,input||'{"publication_state":"recorded_published"}'),'22023','Recorded publication requires explicit external ID or URL');
 perform pg_temp.expect_error(format('select public.preview_project_campaign_placement(%L,%L,%L,null,0,%L::jsonb)',org,project,campaign,input||'{"variant_id":"99999999-9999-4999-8999-999999997299"}'),'42501','Foreign or missing variant cannot borrow an approved source');
 perform pg_temp.expect_error(format('select public.preview_project_campaign_placement(%L,%L,%L,null,0,%L::jsonb)',org,project,campaign,input||'{"account_binding_id":"99999999-9999-4999-8999-999999997299"}'),'42501','Foreign or missing resource cannot use brand equality as authorization');
 perform pg_temp.expect_error(format('select public.preview_project_campaign_placement(%L,%L,%L,null,0,%L::jsonb)',org,project,campaign,input||'{"campaign_plan_version_id":"99999999-9999-4999-8999-999999997299"}'),'55000','Exact plan version is mandatory');
 perform pg_temp.expect_error(format('select public.preview_project_campaign_placement(%L,%L,%L,null,0,%L::jsonb)',org,project,campaign,input||'{"contribution":{"kind":"project_task","id":"99999999-9999-4999-8999-999999997299"}}'),'42501','Missing existing task cannot become a fabricated contribution');

 review:=public.list_project_campaign_placements(org,project,campaign,'','paid','',null,'2026-10-10T00:00:00Z','2026-10-11T00:00:00Z','',0,1);
 perform pg_temp.check_true(review->>'total'='2' and review->>'matching'='1' and review#>>'{items,0,data,mode}'='paid' and review#>>'{items,0,current_contribution,kind}'='engagement_work_item','Calendar filters current revisions by campaign/mode/date with independent totals and canonical Work Item');
 review:=public.list_project_campaign_placements(org,project,campaign,'Facebook','','',null,null,null,'',0,25);
 perform pg_temp.check_true(review#>>'{items,0,current_contribution,due_date}'='2026-10-11' and review#>>'{items,0,original_reference,contribution,due_date}'='2026-10-10','Current canonical Task deadline is derived while original review evidence remains historical');
 review:=public.get_project_campaign_placement_history(org,project,(saved->>'placement_id')::uuid,0,2);
 perform pg_temp.check_true(review->>'total'='4' and jsonb_array_length(review->'items')=2 and review->>'has_more'='true' and review#>>'{items,0,publication_state}'='cancelled','Bounded placement history retains recorded publication and stop revisions');
 perform pg_temp.expect_error(format('select public.list_project_campaign_placements(%L,%L,null,%L,%L,%L,null,%L,%L)',org,project,'','','','2026-01-01T00:00:00Z','2026-12-31T00:00:00Z'),'22023','Unbounded calendar history range rejected');
 perform pg_temp.expect_error(format('select public.get_project_campaign_placement_history(%L,%L,%L)',org,project,'99999999-9999-4999-8999-999999997299'),'42501','Foreign/missing placement cannot read historical references');
 update public.engagement_services set status='on_hold' where id='99999999-9999-4999-8999-999999997171';
 perform pg_temp.check_true(public.list_project_campaign_placements(org,project)#>>'{items,0,reason}'='canonical_source_or_context_unavailable','Calendar preserves immutable placement metadata with unavailable current canonical context');
 update public.engagement_services set status='active' where id='99999999-9999-4999-8999-999999997171';
 perform pg_temp.expect_error('update public.project_campaign_placements set campaign_id=gen_random_uuid()','55000','Original campaign/source identity remains immutable');
 perform pg_temp.expect_error('delete from public.project_campaign_placement_revisions','55000','Placement revision history retained');
 perform pg_temp.expect_error('delete from public.project_campaign_placement_commands','55000','Original placement receipts retained');
end $$;
set local role authenticated;
select pg_temp.check_true(public.list_project_campaign_placements('99999999-9999-4999-8999-999999999901','99999999-9999-4999-8999-999999999974')->>'total'='2','Actual authenticated role reads bounded current placement API');
select pg_temp.expect_error('select * from public.project_campaign_placements','42501','Authenticated cannot bypass bounded native placement APIs');
select pg_temp.expect_error('select * from public.project_campaign_placement_commands','42501','Authenticated cannot read other actor placement receipts directly');
reset role;
select set_config('request.jwt.claim.sub','99999999-9999-4999-8999-999999997299',true);
select pg_temp.expect_error('select public.get_project_campaign_placement_operation(''99999999-9999-4999-8999-999999999901'',''99999999-9999-4999-8999-999999999974'',''99999999-9999-4999-8999-999999997250'')','42501','Unknown actor cannot recover placement receipts');
select pg_temp.check_true(not has_function_privilege('anon','public.preview_project_campaign_placement(uuid,uuid,uuid,uuid,integer,jsonb)','execute') and not has_function_privilege('service_role','public.confirm_project_campaign_placement(uuid,uuid,uuid,uuid,integer,jsonb,text,uuid)','execute'),'Anon/service-role cannot bypass user placement authority');
rollback;
